import {audioLevel} from './studio-audio-levels.js';
const meter=document.getElementById('studio-sound-meter'),status=document.getElementById('studio-sound-status'),button=document.getElementById('studio-sound-test'),stop=document.getElementById('studio-sound-stop');let context=null,source=null,analyser=null,gain=null,timer=null;
async function end(){clearInterval(timer);timer=null;source?.disconnect();gain?.disconnect();analyser?.disconnect();await context?.close().catch(()=>{});context=null;meter.value=0;stop.disabled=true;button.disabled=false;status.textContent='Sound check stopped. Microphones remain available for recording.';}
button.onclick=async()=>{button.disabled=true;try{await end();button.disabled=true;const selected=document.getElementById('studio-audio').value;if(selected==='none')throw Error('Choose a microphone or shared-screen audio first.');let stream=window.studioSelectedAudioStream?.();if(selected==='host'&&!stream){await window.connectStudioMicrophone?.();stream=window.studioSelectedAudioStream?.();}const tracks=stream?.getAudioTracks().filter(t=>t.readyState==='live')||[];if(!tracks.length)throw Error('The selected audio source is not connected. Enable microphone audio on the phone, or connect your microphone.');const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Audio analysis is unavailable in this browser.');context=new Audio();await context.resume();source=context.createMediaStreamSource(new MediaStream(tracks));analyser=context.createAnalyser();analyser.fftSize=2048;gain=context.createGain();gain.gain.value=0;source.connect(analyser);analyser.connect(gain);gain.connect(context.destination);const samples=new Float32Array(analyser.fftSize);stop.disabled=false;timer=setInterval(()=>{if(!tracks.some(t=>t.readyState==='live')){end();status.textContent='Audio source disconnected. Connect it and check sound again.';return;}if(context.state!=='running'){meter.value=0;status.textContent='Audio check paused by browser. Stop and restart sound check.';return;}analyser.getFloatTimeDomainData(samples);const result=audioLevel(samples);meter.value=result.peak;status.textContent=result.state;},100);}catch(e){await end();status.textContent=e.message;}};
stop.onclick=end;document.getElementById('studio-audio').addEventListener('change',end);window.addEventListener('pagehide',end);
